function im_pmwr_xbox_datapack(o, i, x) {
    let end_datapack = o + 120
    let offset_after_datapack = end_datapack
    if (u32(o + 8) || u32(o + 4)) {
        end_datapack += divisible(u32(o + 8) * 4, 32)
        end_datapack += u32(o + 4)
    }

    g.m = end_datapack + divisible(((u32(o + 16) + u32(o + 28) + u32(o + 52)) * 8), 32)

    x.push({
        id: gen_id(),
        sec_id: "jz8p",
        u32_8: u32(o + 8),
        //amount?
        u32_12: u32(o + 12),
        u32_16: u32(o + 16),
        u32_20: u32(o + 20),
        //amount?
        section_24_texture: [],
        u32_28: u32(o + 28),
        u32_32: u32(o + 32),
        //amount?
        u32_48: u32(o + 48),
        //amount?
        u32_52: u32(o + 52),
        u32_56: u32(o + 56),
        section_60_texture_anims: [],
        section_72_rifx: [],
        section_76_riff: [],
        //check this
        section_80: im_string(o + 80 - g.m, o + 91 - g.m),
        u32_92: u32(o + 92),
        u32_112: u32(o + 112),
        index_patch_list: [],
        offset_patch_list: [],
        ordered_section: [],
        section_audio: [],
    });

    im_pmwr_xdx_audio(offset_after_datapack, x[i].section_audio, u32(o + 8))

    // if (u32(o + 8)) {
    //     let calc_audio = o + 120
    //     let afteroffsetlist = calc_audio + divisible((u32(o + 8) * 4), 32)
    //     for (let i = 0; i < u32(o + 8); i++) {
    //         get_pmwr_xdx_audio_list(calc_audio + (i * 4), afteroffsetlist)
    //     }
    // }

    g.datapack_offset = o
    g.datapack_ref = x

    im_pmwr_xdx_get_index_patch_list(o, end_datapack, x[i].index_patch_list)
    im_pmwr_xdx_get_offset_patch_list(o, g.m + u32(o), x[i].offset_patch_list)

    im_pmwr_xdx_ordered(g.m, x[i].ordered_section)

    let offset_start_pmwr_xdx_audio_list = offset_after_datapack + divisible((u32(o + 8) * 4), 32)
    let offset_start_pmwr_xdx_audio_data_2 = offset_start_pmwr_xdx_audio_list + u32(o + 76)
    let offset_end_pmwr_xdx_audio_data_2 = offset_start_pmwr_xdx_audio_list + u32(o + 4)

    switch (g.file_dir_type) {
    case "music":
        im_pmwr_xdx_rifx(offset_start_pmwr_xdx_audio_list, offset_start_pmwr_xdx_audio_data_2, x[i].section_72_rifx);
        im_pmwr_xdx_riff(offset_start_pmwr_xdx_audio_data_2, offset_end_pmwr_xdx_audio_data_2, x[i].section_76_riff);
        break
    }

    for (let ii = 0; ii < u32(o + 20); ii++) {
        im_pmwr_xdx_texture(u32(o + 24) + (ii * 64) + g.m, ii, x[i].section_24_texture)
    }

    for (let ii = 0; ii < u32(o + 48); ii++) {
        im_pmwr_xdx_texture_anims(u32(o + 60) + (ii * 12) + g.m, ii, x[i].section_60_texture_anims)
    }

}

function im_pmwr_xdx_audio(o, x, a) {

    const after_offset_list = o + divisible(a * 4, 32)
    let padding_test = after_offset_list + (a * 32)

    x.push({
        sec_id: "audi",
        sound: []
    })

    for (let i = 0; i < a; i++) {
        padding_test = im_pmwr_xdx_audio_00(after_offset_list + u32(o + (i * 4)), x[0].sound, i)
    }

    return padding_test

    function im_pmwr_xdx_audio_00(o, x, i) {
        x.push({
            sec_id: "ad00",
            id: gen_id(),
            u32_8: u32(o + 8),
            soundsamplerate: u32(o + 12),
            u32_20: u32(o + 20),
            sound_data: 0,
            padding: (u32(o + 0) + after_offset_list) - padding_test
        })
        const start_offset = u32(o + 0) + after_offset_list
        const sound_buffer = convert_arraybuffer_base64(buffer.slice(start_offset, start_offset + u32(o + 4)))

        x[i].sound_data = sound_buffer

        return start_offset + u32(o + 4)

    }

}

function im_pmwr_xdx_rifx(o, e, x) {
    x.push({
        id: gen_id(),
        sec_id: "imps",
        buffer: convert_arraybuffer_base64(buffer.slice(o, e)),
    });

}

function im_pmwr_xdx_riff(o, e, x) {
    x.push({
        id: gen_id(),
        sec_id: "ad2o",
        buffer: convert_arraybuffer_base64(buffer.slice(o, e)),
    });

}
function im_pmwr_xdx_get_index_patch_list(o, patch_offset, x) {
    let texture_offset = patch_offset

    patch_offset += u32(g.datapack_offset + 16) * 8
    let texture_animation_offset = patch_offset

    patch_offset += u32(g.datapack_offset + 52) * 8
    let sound_offset = patch_offset

    // patch_offset += u32(g.datapack_offset + 28) * 8
    // let model_offset = patch_offset

    // patch_offset += u32(g.datapack_offset + 56) * 8
    // let general_offset = patch_offset

    x.push({
        sec_id: "ipll",
        texture: im_patch_list(texture_offset, u32(g.datapack_offset + 16), 't'),
        texture_animation: im_patch_list(texture_animation_offset, u32(g.datapack_offset + 52), 'a'),
        sound: im_patch_list(sound_offset, u32(g.datapack_offset + 28), 's'),
        // model: im_patch_list(model_offset, u32(g.datapack_offset + 56), 'm'),
    })

    g.texture_patch_ref = x[0].texture
    g.animation_patch_ref = x[0].texture_animation
    g.sound_patch_ref = x[0].sound
}

function im_pmwr_xdx_get_offset_patch_list(o, patch_offset, x) {
    let model_offset = patch_offset

    patch_offset += u32(g.datapack_offset + 56) * 8
    let general_offset = patch_offset

    x.push({
        sec_id: "opll",
        model: im_patch_list(model_offset, u32(g.datapack_offset + 56), 'm'),
    })

    g.model_ref = x[0].model

    log_array.p_offset.offset = general_offset
    for (let i = 0; i < u32(g.datapack_offset + 12); i++) {
        log_array.p_offset.array.push(u32(general_offset + (i * 4)))
    }

    log_array.p_offset.array.sort(function(a, b) {
        return a - b;
    });

}

